{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_counts_as_unflagged():
    assert monitor_flag_rate([{"flagged": None}, {"flagged": True}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_last_record_per_id_wins_before_sorting():
    first = {"id": "a", "day": 8, "flagged": True}
    last = {"id": "a", "day": 2, "flagged": False}
    b = {"id": "b", "day": 2, "flagged": True}
    z = {"id": "z", "day": 1, "flagged": True}
    assert dedupe_transcripts([b, first, z, last]) == [z, last, b]


def test_parser_skips_comments_and_blank_lines_and_trims_fields():
    lines = ["", " \t", "  # comment", " a , 3 , 1 ", " b,4, 0", "c, 5, "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 3, "flagged": True},
        {"id": "b", "day": 4, "flagged": False},
        {"id": "c", "day": 5, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,today,1"])
def test_parser_reports_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_transcript_log([" # comment", "", bad_line])


def test_daily_counts_and_trailing_window():
    events = parse_transcript_log(["a,1,1", "b,2,1", "c,2,1", "d,3,0", "e,4,1", "f,5,1"])
    counts = daily_flag_counts(events, 2, 4)
    assert counts == [2, 0, 1]
    assert daily_flag_counts(events, 4, 2) == []
    assert flags_in_window(counts, 2) == 1
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 10) == 3


def test_summary_uses_pooled_rate_and_calendar_days():
    groups = {"a": parse_transcript_log(["x,1,1"]), "b": parse_transcript_log(["y,1,0", "z,4,0"]), "empty": []}
    assert pooled_flag_rate(groups) == 1 / 3
    assert monitor_summary(groups, 3) == {"rate": 0.333, "groups": 2, "recent": 0}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "groups": 0, "recent": 0}


def test_group_reports_order_and_empty_groups():
    groups = {"z": [{"flagged": True}], "a": [{"flagged": True}], "empty": [], "b": [{"flagged": False}]}
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("empty", None), ("z", 1.0)]


@pytest.mark.parametrize("counts, expected", [([], 0), ([-1, 0], 0), ([1, 1, -1, 1, 0, 2, 1, 1], 3)])
def test_longest_streak_counts_consecutive_positive_entries(counts, expected):
    assert longest_flag_streak(counts) == expected
